from pathlib import Path
root=Path(__file__).parent/'src'/'web'
css='''
:root{--bg:#0a111b;--surface:#111d2b;--surface2:#152435;--line:#26374b;--text:#edf4fb;--muted:#9eb0c5;--accent:#83e4bc;--blue:#88bcff;--warn:#ffc782;--red:#ff9b9b}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.55 system-ui,-apple-system,Segoe UI,sans-serif}a{color:var(--blue)}.wrap{max-width:1120px;margin:auto;padding:32px 30px 64px}header{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:0 0 36px}.brand{font-size:21px;font-weight:760;letter-spacing:-.5px}.logo{display:inline-block;color:var(--accent);font-size:29px;margin-right:9px;vertical-align:-2px}.tag{font:11px/1.4 ui-monospace,monospace;letter-spacing:1.3px;text-transform:uppercase;border:1px solid var(--line);border-radius:6px;padding:7px 10px;color:var(--muted)}.eyebrow{font-size:11px;font-weight:700;letter-spacing:2px;color:var(--accent);text-transform:uppercase}h1{font-size:44px;line-height:1.12;letter-spacing:-1.7px;margin:12px 0 16px;max-width:800px}h2{font-size:21px;line-height:1.3;margin:0 0 14px;letter-spacing:-.4px}h3{font-size:15px;margin:0 0 9px}.lead{font-size:18px;max-width:750px;color:var(--muted);margin:0 0 24px}.note{padding:13px 16px;border:1px solid #624b2d;border-radius:9px;background:#211d17;color:var(--warn);font-size:13px;margin:22px 0}.grid{display:grid;grid-template-columns:1.05fr 1fr;gap:20px;margin-top:22px}.card{min-width:0;border:1px solid var(--line);border-radius:14px;padding:24px;background:var(--surface)}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:24px 0}.metric{padding:18px;border:1px solid var(--line);border-radius:11px;background:var(--surface)}.num{font-size:30px;font-weight:730;letter-spacing:-1px}.label{font-size:12px;color:var(--muted)}.muted{color:var(--muted)}.small{font-size:12px}.row{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:12px}.stack{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.pill{display:inline-block;border:1px solid var(--line);background:var(--surface2);border-radius:99px;padding:6px 12px;font-size:12px;color:var(--accent)}button,.btn{background:var(--accent);color:#092014;font:650 14px system-ui;border:0;border-radius:8px;padding:12px 17px;cursor:pointer;display:inline-block;text-decoration:none}button:hover,.btn:hover{filter:brightness(1.08)}button:disabled{opacity:.38;cursor:not-allowed}.secondary{background:var(--surface2);color:var(--text);border:1px solid var(--line)}.danger{background:#422328;color:var(--red);border:1px solid #7b4148}input,textarea,select{width:100%;background:#0b1521;color:var(--text);border:1px solid var(--line);border-radius:8px;padding:11px;font:14px system-ui}textarea{font:11px/1.55 ui-monospace,monospace;resize:vertical}input[type=checkbox]{width:18px;height:18px;margin:3px 10px 0 0;flex:none;accent-color:var(--accent)}label{display:block;color:var(--muted);font-size:13px;margin-bottom:8px}.check{display:flex;font-size:13px;line-height:1.5;margin:18px 0;color:var(--text)}.fieldrow{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.status{font-size:22px;font-weight:680;letter-spacing:-.5px;color:var(--accent);margin:12px 0}.progress{height:8px;border-radius:99px;background:#28394b;overflow:hidden;margin:14px 0}.fill{height:100%;background:var(--accent);transition:width .4s;width:0}.details{border-top:1px solid var(--line);margin-top:20px;padding-top:17px}.break{overflow-wrap:anywhere}.err{font-size:12px;color:var(--warn);min-height:22px;margin-top:10px;overflow-wrap:anywhere}.flow{display:flex;gap:14px;align-items:center;justify-content:space-between;margin:26px 0}.flow div{flex:1;background:var(--surface2);padding:18px 14px;border:1px solid var(--line);border-radius:10px;font-size:13px}.flow b{display:block;color:var(--accent);font-size:12px;margin-bottom:5px}footer{border-top:1px solid var(--line);margin-top:32px;padding-top:20px;color:var(--muted);font-size:12px}.mono{font-family:ui-monospace,monospace}table{width:100%;border-collapse:collapse;font-size:12px}td,th{text-align:left;padding:10px 8px;border-bottom:1px solid var(--line)}th{color:var(--muted);font-weight:500}.wide{grid-column:1/-1}.steps{counter-reset:s}ol{padding-left:20px;color:var(--muted)}li{margin:8px 0}.biglink{display:block;margin:8px 0}summary{cursor:pointer;color:var(--blue);font-size:12px}.hidden{display:none!important}
@media(max-width:760px){.wrap{padding:20px 17px 40px}h1{font-size:32px}.grid{grid-template-columns:1fr}.cards{grid-template-columns:1fr 1fr}.flow{align-items:stretch;flex-direction:column}.flow span{display:none}.card{padding:19px}.fieldrow{grid-template-columns:1fr}header{padding-bottom:27px}.tag{font-size:9px}}
'''
api='''
const hash=location.hash.slice(1);if(hash){sessionStorage.setItem('keyai-token',hash);history.replaceState(null,'',location.pathname)}
const token=sessionStorage.getItem('keyai-token')||'';
async function api(path,data){const r=await fetch(path,{method:data===undefined?'GET':'POST',headers:{'X-Session-Token':token,'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});const j=await r.json();if(!r.ok)throw new Error(j.error||('HTTP '+r.status));return j}
const $=s=>document.getElementById(s);const text=(id,v)=>{$(id).textContent=v};
async function action(fn){try{await fn();text('error','');await refresh()}catch(e){text('error',e.message)}}
'''
def page(name,title,body,js):
 html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title><style>'+css+'</style></head><body><main class="wrap">'+body+'</main><script>'+js+'</script></body></html>'
 root.joinpath(name).write_text(html)
header='<header><div class="brand"><span class="logo">◈</span>KeyAI Commons</div><span class="tag">Research pilot · v0.1.0</span></header>'
page('client.html','KeyAI Commons | Participant',header+'''
<div class="eyebrow">Your computer. Your permission.</div><h1>Contribute on your terms.</h1>
<p class="lead">Connect to a research network. Approve a short session. Training starts only when the operator sends an approved task.</p>
<div class="note" id="buildnote">Experimental CPU-only pilot. A 65-parameter neural network, not a language model. No GPU jobs, financial rewards or ownership rights in this release.</div>
<div class="cards"><div class="metric"><div class="num" id="accepted">0</div><div class="label">Verified updates this session</div></div><div class="metric"><div class="num" id="modelversion">0</div><div class="label">Global model version</div></div><div class="metric"><div class="num" id="timeleft">Off</div><div class="label">Permission remaining</div></div><div class="metric"><div class="num">CPU</div><div class="label">1 paced training worker · no GPU</div></div></div>
<div class="grid"><section class="card"><div class="row"><h2>Your participation</h2><span class="pill" id="connection">Not connected</span></div><div class="status" id="status">Waiting for setup</div><div class="muted small" id="progresslabel">No training is running.</div><div class="progress"><div class="fill" id="bar"></div></div>
<label for="minutes">Allow approved tasks for</label><select id="minutes"><option value="5">5 minutes</option><option value="15" selected>15 minutes</option><option value="30">30 minutes</option><option value="60">60 minutes</option></select>
<label class="check"><input type="checkbox" id="agree"><span>I allow this network to run the built-in synthetic training task during this session. It uses electricity and may create heat. I can pause at any time. No personal files or chats are used.</span></label>
<div class="stack"><button id="allow" disabled>Enable participation</button><button class="danger" id="pause">Pause now</button></div><div class="err" id="error"></div>
<div class="details small muted">Reopening the app never restores permission automatically. The operator cannot run a terminal, install software or change the built-in workload.</div></section>
<section class="card"><h2>Join a network</h2><p class="small muted">Paste the connection code from the organizer. It contains the network address, a pinned signing key and an enrollment invitation. Never paste an operator/admin link here.</p><label for="code">Network connection code</label><textarea id="code" rows="4" placeholder="Paste the organizer's connection code"></textarea><button class="secondary" id="connect" style="margin-top:10px">Connect</button>
<div class="details"><div class="label">Connected coordinator</div><p class="small mono break" id="network">Not configured</p><div class="label">Your pseudonymous node ID</div><p class="small mono break" id="node">Not registered</p><details><summary>Signing key and privacy</summary><p class="small mono break" id="key"></p><p class="small muted">The server receives a random node ID, OS/architecture, readiness, model updates and connection IP. This client does not read documents, browser history or private training data. Local state can be removed by deleting the KeyAICommons configuration folder.</p></details></div></section>
<section class="card wide"><div class="row"><div><h2>Know exactly what is running.</h2><span class="muted small">tiny-xor-mlp-v1 · Synthetic 2D classification · 2 → 16 → 1 neurons</span></div><button class="secondary" id="exit">Exit application</button></div><div class="flow"><div><b>01 · YOU APPROVE</b>A time-limited session</div><span>→</span><div><b>02 · OPERATOR STARTS</b>A signed, bounded training task</div><span>→</span><div><b>03 · YOU CAN STOP</b>Pause or close the application</div></div><p class="small muted">Closing only this browser tab does not quit the app. Use Exit application, close the app's console window, or let the session timer expire. A job also stops on coordinator loss at the next polling check, or after its 30-second local hard deadline.</p></section></div>
<footer>Open source · No auto-start · No remote shell · No crypto mining · No silent updates<br>This pilot is not independently security-audited. Use only with a trusted organizer.</footer>
''',api+'''
let connected=false;
const names={not_connected:'Not connected',paused:'Paused. You are in control.',waiting_for_operator:'Ready. Waiting for the operator.',training:'Training an approved task',upload_pending:'Sending your result',contribution_verified:'Your update was verified',network_unavailable:'Network unavailable. No new work.',session_finished:'Session finished. Permission expired.',operator_stopped:'Operator stopped this round.',task_cancelled:'Task stopped',task_rejected:'Unapproved task rejected',storage_error:'Local storage error'};
async function refresh(){const s=await api('/api/status');connected=s.connected;if(s.internet_enabled===false)text('buildnote','LOCAL-TEST BUILD. Internet enrollment is disabled because this binary was built with '+s.toolchain+'. Use LOCAL-DEMO to test it; a current, reviewed rebuild is required before public deployment. CPU-only tiny model, no financial or ownership rights.');text('accepted',s.accepted_this_session);text('modelversion',s.model_version);text('status',names[s.status]||s.status);text('connection',s.connected?'Connected':'Not connected');text('timeleft',s.consent?Math.max(0,Math.ceil((s.consent_until-Date.now()/1000)/60))+' min':'Off');text('network',s.network_url||'Not configured');text('node',s.node_id||'Not registered');text('key',s.public_key||'No signing key');text('progresslabel',s.busy?'Round '+s.round+' · batch '+s.progress+' / '+s.total:'No training is running.');$('bar').style.width=(s.busy&&s.total?100*s.progress/s.total:0)+'%';$('allow').disabled=!s.connected||!$('agree').checked||s.consent;$('connect').disabled=s.consent||s.busy;if(s.last_error)text('error',s.last_error)}
$('agree').onchange=()=>refresh().catch(e=>text('error',e.message));$('connect').onclick=()=>action(()=>api('/api/connect',{code:$('code').value}));$('allow').onclick=()=>action(()=>api('/api/consent',{allow:true,minutes:Number($('minutes').value),acknowledged:$('agree').checked}));$('pause').onclick=()=>action(()=>api('/api/pause',{}));$('exit').onclick=async()=>{try{await api('/api/exit',{});document.body.innerHTML='<main class="wrap"><h1>Application closed.</h1><p>No training is running. You may close this tab.</p></main>';clearInterval(timer)}catch(e){text('error',e.message)}};
const timer=setInterval(()=>refresh().catch(e=>text('error',e.message)),1000);refresh().catch(e=>text('error',e.message));
''')
page('admin.html','KeyAI Commons | Operator',header+'''
<div class="eyebrow">Private operator console</div><h1>Launch a round.<br>Not a remote takeover.</h1><p class="lead">Only consenting, connected nodes receive work. The participant's pause button always wins.</p><div class="note">PRIVATE CONTROL PANEL. Do not share this URL or the coordinator's state folder. Share only the connection code below. This pilot supports up to 32 nodes per round, not millions.</div>
<div class="cards"><div class="metric"><div class="num" id="online">0</div><div class="label">Nodes recently online</div></div><div class="metric"><div class="num" id="ready">0</div><div class="label">Nodes with active permission</div></div><div class="metric"><div class="num" id="accuracy">0%</div><div class="label">Synthetic validation accuracy</div></div><div class="metric"><div class="num" id="loss">0</div><div class="label">Validation loss · lower is better</div></div></div>
<div class="grid"><section class="card"><h2>Training control</h2><div class="fieldrow"><div><label for="steps">Local batches</label><input id="steps" type="number" min="10" max="1200" value="800"></div><div><label for="nodes">Target nodes</label><input id="nodes" type="number" min="1" max="32" value="1"></div><div><label for="seconds">Round deadline (s)</label><input id="seconds" type="number" min="30" max="240" value="60"></div></div><div class="status" id="round">No active round</div><div class="small muted" id="rounddetails">Start only after a participant has enabled permission.</div><div class="progress"><div class="fill" id="bar"></div></div><div class="stack"><button id="start">Start round</button><button class="secondary" id="finalize" disabled>Aggregate received</button><button class="danger" id="stop" disabled>Stop round</button></div><div class="err" id="error"></div><p class="small muted">Each worker trains the same base model on a separate synthetic sample stream. Verified updates are averaged. At the deadline, available verified results are used; absent nodes do not block the network forever. Stop discards the active round.</p></section>
<section class="card"><h2>Invite participants</h2><p class="small muted">Give participants this code along with the client. A public rollout needs a stable HTTPS coordinator URL, rebuilt and reviewed binaries, and an external deployment test.</p><label for="code">Participant connection code · safe to share with testers</label><textarea id="code" rows="4" readonly></textarea><button class="secondary" id="copy" style="margin-top:10px">Copy connection code</button><div class="details"><div class="label">Network endpoint</div><p id="endpoint" class="small mono break"></p><div class="label">Signing public key</div><p id="key" class="small mono break"></p></div></section>
<section class="card wide"><div class="row"><h2>Measured model history</h2><span class="pill" id="modelversion">Version 0</span></div><div style="overflow:auto"><table><thead><tr><th>Round</th><th>Version</th><th>Nodes</th><th>Loss</th><th>Accuracy</th><th>Checkpoint hash</th></tr></thead><tbody id="history"></tbody></table></div><div class="details small muted">The verifier fully replays every task in this pilot. This detects incorrect submitted results but repeats the compute cost. It is not a scalable proof-of-compute system, a proof of unique humans, or a demonstration that this network is cheaper than a datacenter.</div></section></div>
<footer>No automatic campaigns after restart. No GPU or LLM training in v0.1.0. The public status page contains aggregate counts, not participant IDs. Operator commands are unavailable on the public API listener.</footer>
''',api+'''
async function refresh(){const s=await api('/api/status');text('online',s.online);text('ready',s.ready);text('accuracy',(100*s.accuracy).toFixed(1)+'%');text('loss',s.loss.toFixed(4));text('modelversion','Version '+s.model_version);const r=s.round;text('round',r.running?'Round '+r.number+' in progress':'No active round');text('rounddetails',r.running?r.verified+' verified / '+r.target+' target · '+r.assigned+' assigned · '+Math.max(0,Math.ceil(r.deadline-Date.now()/1000))+'s left':'Ready nodes: '+s.ready+' · Total registered: '+s.registered);$('bar').style.width=(r.running?100*r.verified/r.target:0)+'%';$('start').disabled=r.running;$('stop').disabled=!r.running;$('finalize').disabled=!r.running;$('history').replaceChildren();for(const h of (s.history||[]).slice(-10).reverse()){const tr=document.createElement('tr');for(const v of [h.round,h.version,h.participants,h.loss.toFixed(4),(100*h.accuracy).toFixed(1)+'%',h.hash.slice(0,18)]){const td=document.createElement('td');td.textContent=v;tr.appendChild(td)}$('history').appendChild(tr)}if(s.error)text('error',s.error)}
$('start').onclick=()=>action(()=>api('/api/start',{steps:Number($('steps').value),nodes:Number($('nodes').value),seconds:Number($('seconds').value)}));$('stop').onclick=()=>action(()=>api('/api/stop',{}));$('finalize').onclick=()=>action(()=>api('/api/finalize',{}));$('copy').onclick=async()=>{try{await navigator.clipboard.writeText($('code').value);$('copy').textContent='Copied'}catch(e){$('code').select();text('error','Select and copy the connection code.')}};
api('/api/config').then(c=>{$('code').value=c.connection_code;text('endpoint',c.public_url);text('key',c.public_key)}).catch(e=>text('error',e.message));setInterval(()=>refresh().catch(e=>text('error',e.message)),1000);refresh().catch(e=>text('error',e.message));
''')
page('landing.html','KeyAI Commons | A voluntary AI research network',header+'''
<div class="eyebrow">An open experiment in shared intelligence</div><h1>Many computers.<br>One shared experiment.</h1><p class="lead">A voluntary network for AI research. Download a client, choose when to contribute, and keep the power to stop.</p><div class="stack"><a class="btn" href="#download">Explore the pilot</a><a class="btn secondary" href="#how">How it works</a></div><div class="note">v0.1.0 is a private, CPU-only engineering pilot. It trains a tiny synthetic neural network. It does not yet train or serve a large language model. Public deployment is not included or claimed.</div>
<div class="cards"><div class="metric"><div class="num" id="online">Not live</div><div class="label">Nodes online · live API only</div></div><div class="metric"><div class="num" id="ready">Not live</div><div class="label">Participants currently ready</div></div><div class="metric"><div class="num" id="versions">Not live</div><div class="label">Verified model versions</div></div><div class="metric"><div class="num">You</div><div class="label">Always control your device</div></div></div>
<section class="card" id="how"><h2>Permission first. Training second.</h2><div class="flow"><div><b>01 · CONNECT</b>Install nothing system-wide. Open the portable client and enter a network code.</div><span>→</span><div><b>02 · CHOOSE</b>Allow a short session. No training runs without your permission.</div><span>→</span><div><b>03 · CONTRIBUTE</b>The organizer starts a bounded task. Your client verifies the signature.</div><span>→</span><div><b>04 · KEEP CONTROL</b>Pause instantly, exit the app, or let your session expire.</div></div></section>
<div class="grid"><section class="card"><h2>What the pilot proves</h2><p class="muted">A signed task can reach consenting clients. Clients train separate sample streams. Verified updates create a shared checkpoint. Disconnected nodes do not hold a round open indefinitely.</p><p class="small muted">Training uses a 2 → 16 → 1 neural network with 65 parameters. This deliberately small workload makes the mechanism inspectable before any GPU-scale work.</p></section><section class="card"><h2>What it does not promise</h2><p class="muted">No million-node benchmark. No frontier model. No distributed weight shards yet. No token sale, paid credits or legal ownership stake. No claim of independent security certification.</p><p class="small muted">The next gates are external machine testing, security review, scalable result validation, real GPU training and stable public hosting.</p></section>
<section class="card wide" id="download"><h2>Tester downloads</h2><p class="muted">Use these only after the organizer has supplied a working network code. This directory must be hosted together with its downloads folder. No executable downloads are served by the coordinator API.</p><div class="stack"><a class="btn" href="downloads/KeyAI-Commons-Windows-x64.zip">Windows x64</a><a class="btn secondary" href="downloads/KeyAI-Commons-Linux-x64.zip">Linux x64</a><a class="btn secondary" href="downloads/KeyAI-Commons-macOS-arm64.zip">macOS Apple silicon</a><a class="btn secondary" href="downloads/KeyAI-Commons-macOS-x64.zip">macOS Intel</a><a class="btn secondary" href="downloads/KeyAI-Commons-Source.zip">Source &amp; tests</a></div><p class="small muted">Unsigned developer builds. Windows SmartScreen or macOS Gatekeeper may warn or block execution. Do not disable your security software. Public distribution needs appropriate signing/notarization and a current, reviewed build.</p></section></div>
<footer>KeyAI Commons · Independent research project, not affiliated with OpenAI.<br>Open source code under MIT. Participation is voluntary and gives no equity or financial claim.</footer>
''','''
async function refresh(){try{const r=await fetch('/v1/status');if(!r.ok)return;const s=await r.json();document.getElementById('online').textContent=s.online;document.getElementById('ready').textContent=s.ready;document.getElementById('versions').textContent=s.model_version}catch(e){}}refresh();setInterval(refresh,5000);if(location.protocol!=='file:'){fetch('/v1/info').then(r=>r.json()).then(info=>{if(info.pilot)document.querySelectorAll('#download a').forEach(a=>{a.removeAttribute('href');a.setAttribute('aria-disabled','true');a.style.opacity='.4';a.title='Downloads are supplied separately by the organizer';})}).catch(()=>{});}
''')
print('Built',len(list(root.glob('*.html'))),'embedded interfaces')
